he old CPI data via alternate methods\n# Using different series or data sources\n\n# Let's look at FRED series list\nurl = \"https://fred.stlouisfed.org/series/CPIAUCSL\"\ntry:\n    req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})\n    response = urllib.request.urlopen(req, timeout=15)\n    content = response.read().decode()\n    # Look for when the series starts\n    if '1947' in content:\n        print(\"Series starts in 1947\")\nexcept Exception as e:\n    print(f\"Error: {e}\")\n\n# Let me try a completely different approach - use the BLS public data\n# The BLS has older data but needs specific query\n\n# Let me try to find the data by using the BLS with a different API call\n# Try using the older historical series\nimport json\n\n# Try calling BLS for the old CPI series\n# CUUR0000SA0L1E is supposed to be the legacy series\n\nurl = \"https://api.bls.gov/publicAPI/v2/timeseries/data/\"\n# Try different series\nseries_to_try = [\"CUUR0000SA0\", \"CWUR0000SA0\", \"CUUR0000SA0L1E\", \"AWTR0000SA0\"]\n\nfor series_id in series_to_try:\n    print(f\"\\nTrying {series_id}:\")\n    payload = {\n        \"seriesid\": [series_id],\n        \"startyear\": \"1946\",\n        \"endyear\": \"1948\",\n        \"catalog\": False\n    }\n    \n    req = urllib.request.Request(\n        url, \n        data=json.dumps(payload).encode('utf-8'),\n        headers={'Content-Type': 'application/json', 'User-Agent': 'Mozilla/5.0'}\n    )\n    \n    try:\n        response = urllib.request.urlopen(req, timeout=15)\n        data = json.loads(response.read().decode())\n        \n        if data.get('status') == 'REQUEST_SUCCEEDED':\n            series_data = data.get('Results', {}).get('series', [])\n            if series_data and series_data[0].get('data'):\n                count = 0\n                for item in series_data[0]['data']:\n                    if 'M' in str(item.get('period', '')):\n                        print(f\"  {item.get('year')} {item.get('period')}: {item.get('value')}\")\n                        count += 1\n                        if count > 5:\n                            break\n            else:\n                print(\"  No data returned\")\n        else:\n            print(f\"  Status: {data.get('status')}\")\n    except Exception as e:\n        print(f\"  Error: {e}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
